params.add('hole_offset_y', 4.94, min=3.0, max=35.0, expression='flange_height * 0.38', semantic_type='hole_spacing')
params.add('hole_radius', 1.14, min=0.5, max=4.0, semantic_type='hole_radius')
params.add('pocket_length', 15.1, min=12.0, max=70.0, expression='flange_width * 0.49', semantic_type='pocket_width')
