params.add('lower_width', 21.4, min=12.0, max=80.0, semantic_type='primitive_width')
params.add('upper_radius', 7.14, min=3.0, max=14.0, semantic_type='loft_upper_radius')

part = Part('flluma_0005001', category='lofted_transition', parameters=params, seed=20265518, sample_id='flluma_0005001', units='mm')
sketch = part.sketch_rectangle(name='loft_lower_rect_profile', width=params['lower_width'], height=params['lower_height'], semantic_type='loft_profile')
sketch_2 = part.sketch_circle(name='loft_upper_round_profile', radius=params['upper_radius'], segments=48, semantic_type='loft_profile')
moved = part.translate(name='place_upper_loft_profile', target=sketch_2, offset=[0.0, 0.0, 20.1], semantic_type='placement')
loft = part.loft(name='loft_transition_solid', profiles=[sketch, moved], semantic_type='lofted_solid')
box = part.box(name='lofted_transition_flange_seed', length=params['flange_width'], width=params['flange_height'], height=params['flange_thickness'], semantic_type='flange')
