join = part.boolean_join(name='join_lofted_transition_flange', target=loft, tool=moved_2, semantic_type='flange')
holes = part.hole_pattern(name='lofted_transition_bolt_holes', target=join.top_face(), radius=params['hole_radius'], depth='through', positions=[[-12.67, -4.94], [12.67, -4.94], [-12.67, 4.94], [12.67, 4.94]], semantic_type='bolt_hole_pattern')

